const TABS={
 seller:[['s.home',['Home','الرئيسية'],'home'],['s.orders',['Orders','الطلبات'],'box'],['s.products',['Products','المنتجات'],'tag'],['s.inbox',['Inbox','الرسائل'],'chat'],['s.more',['More','المزيد'],'menu']],
 admin:[['a.sellers',['Sellers','البائعون'],'store'],['a.listings',['Listings','المنتجات'],'tag'],['a.disputes',['Disputes','النزاعات'],'scale'],['a.payouts',['Payouts','المدفوعات'],'wallet'],['a.commission',['Commission','العمولة'],'pct']],
 buyer:[['b.shop',['Shop','تسوّق'],'store'],['b.cart',['Cart','السلة'],'cart'],['b.orders',['Orders','الطلبات'],'box'],['b.inbox',['Messages','الرسائل'],'chat']]};
