 if(isNav){ ['pdraft','tiers','locDraft','agreeChk','disc','spon','mem','ret','rate','bq','csv','smode','swin','profDraft'].forEach(k=>UI[k]=null); UI.err={}; UI.sday=0; }
 let out; try{ out=scr.render(P.q); }catch(err){ console.error(err); out=empty('alert',t('Something went wrong','حدث خطأ'),String(err&&err.message||err)); }
