 const tabsL=TABS[role]; const showTabs=!scr.noTabs&&!(role==='seller'&&!unlocked()&&!scr.tabOk);
 const nUnread=S.notifs.filter(n=>n.who===role&&!n.read).length;
 const sc=window.scrollY;
 DOC.lang=lang; DOC.dir=lang==='ar'?'rtl':'ltr';
