/* ---------- sheet / toast ---------- */
let sheetRet=null;
const sheet=MK.sheet=(title,body,o={})=>{ closeSheet(true); sheetRet=document.activeElement; const d=document.createElement('div'); d.className='sh-wrap'; d.innerHTML=`<div class="scrim" data-act="shclose"></div><div class="sheet" role="dialog" aria-modal="true" aria-labelledby="sh-t"><div class="sh-h"><h2 id="sh-t">${title}</h2><button type="button" class="ib" data-act="shclose" aria-label="${t('Close','إغلاق')}">${I('x',20)}</button></div><div class="sh-b">${body}</div></div>`; document.body.appendChild(d); document.getElementById('mk').setAttribute('aria-hidden','true'); const f=d.querySelector('.sh-b input,.sh-b select,.sh-b textarea,.sh-b button')||d.querySelector('button'); f&&f.focus(); };
const closeSheet=MK.closeSheet=(silent)=>{ const w=document.querySelectorAll('.sh-wrap'); if(!w.length) return; w.forEach(x=>x.remove()); document.getElementById('mk').removeAttribute('aria-hidden'); if(!silent&&sheetRet&&document.contains(sheetRet)) sheetRet.focus(); };
let tT=0; const toast=MK.toast=msg=>{ const el=document.getElementById('mk-toast'); el.textContent=''; clearTimeout(tT); setTimeout(()=>{ el.textContent=msg; el.classList.add('on'); },30); tT=setTimeout(()=>el.classList.remove('on'),3800); };

/* ---------- forms + validation ---------- */
const form=MK.form=(root)=>{ root=root||document; const o={}; root.querySelectorAll('input[name],select[name],textarea[name]').forEach(el=>{ if(el.type==='checkbox') o[el.name]=el.checked; else if(el.type==='radio'){ if(el.checked) o[el.name]=el.value; else if(!(el.name in o)) o[el.name]=''; } else o[el.name]=el.value.trim(); }); return o; };
const check=MK.check=(rules)=>{ UI.err={}; rules.forEach(([n,ok,msg])=>{ if(!UI.err[n]&&!ok) UI.err[n]=msg; }); const bad=Object.keys(UI.err); if(bad.length){ UI.focusBad=true; toast(t(`Fix ${bad.length} field${bad.length>1?'s':''} to continue`,`صحّح ${bad.length} حقل للمتابعة`)); } return !bad.length; };
const clearErr=MK.clearErr=()=>{ UI.err={}; };
const ibanOk=MK.ibanOk=v=>{ v=v.replace(/\s+/g,'').toUpperCase(); if(!/^SA\d{22}$/.test(v)) return false; const s=v.slice(4)+v.slice(0,4); let r=0; for(const ch of s){ const d=/[A-Z]/.test(ch)?String(ch.charCodeAt(0)-55):ch; for(const x of d) r=(r*10+Number(x))%97; } return r===1; };

/* ---------- events ---------- */
const ACT=MK.ACT;
document.addEventListener('click',e=>{ const g=e.target.closest('[data-go]'); const a=e.target.closest('[data-act]');
 if(a&&(a.tagName==='INPUT'||a.tagName==='SELECT')) return;
 if(a){ const f=ACT[a.dataset.act]; if(f){ e.preventDefault(); f(a.dataset.arg,a,e); return; } }
 if(g){ e.preventDefault(); const [p,q]=g.dataset.go.split('?'); clearErr(); go(p,q?Object.fromEntries(new URLSearchParams(q)):null); } });
document.addEventListener('change',e=>{ const a=e.target.closest('[data-act]'); if(a&&(a.tagName==='INPUT'||a.tagName==='SELECT')){ const f=ACT[a.dataset.act]; f&&f(a.type==='checkbox'?String(a.checked):a.value,a,e); } });
document.addEventListener('keydown',e=>{ const sh=document.querySelector('.sh-wrap .sheet');
 if(e.key==='Escape'&&sh){ closeSheet(); return; }
 if(e.key==='Tab'&&sh){ const f=[...sh.querySelectorAll('button:not([disabled]),input,select,textarea,a[href]')]; if(!f.length) return; const a=f[0],z=f[f.length-1]; if(e.shiftKey&&document.activeElement===a){ e.preventDefault(); z.focus(); } else if(!e.shiftKey&&document.activeElement===z){ e.preventDefault(); a.focus(); } }
 const tb=e.target.closest('[role=tab]'); if(tb&&(e.key==='ArrowRight'||e.key==='ArrowLeft')){ const L=[...tb.parentNode.querySelectorAll('[role=tab]')]; let i=L.indexOf(tb)+((e.key==='ArrowRight')!==(DOC.dir==='rtl')?1:-1); i=(i+L.length)%L.length; L[i].click(); setTimeout(()=>{ const n=document.querySelectorAll('[role=tab]')[i]; n&&n.focus(); },0); } });
window.addEventListener('hashchange',()=>{ closeSheet(true); render(true); });
window.addEventListener('storage',e=>{ if(e.key!==KEY) return; load(); const ae=document.activeElement; if(ae&&/INPUT|TEXTAREA|SELECT/.test(ae.tagName)&&ae.closest('#main')) { UI.pending=true; return; } if(!document.querySelector('.sh-wrap')) rr(); });
document.addEventListener('focusout',()=>{ if(UI.pending){ setTimeout(()=>{ const ae=document.activeElement; if(!(ae&&/INPUT|TEXTAREA|SELECT/.test(ae.tagName))&&!document.querySelector('.sh-wrap')){ UI.pending=false; rr(); } },50); } });
ACT.skip=()=>{ const m=document.getElementById('main'); m&&m.focus(); };
