const CSV_COLS=['title_en','title_ar','category','pack_en','price_excl_vat','moq_cases','tier1_from','tier1_pct','storage','shelf_life_days','best_before','quantity_cases'];
const SAMPLE_CSV=[CSV_COLS.join(','),'Sunflower oil 18 L tin (sample),زيت دوار الشمس 18 لتر (عينة),oil,Tin · 18 L,92,2,10,4,ambient,365,2027-09-30,80','Tomato paste 400 g × 24 (sample),معجون طماطم 400 جم × 24 (عينة),canned,Case · 24 cans,55,1,8,3,ambient,540,2027-12-31,150','Frozen chicken 1 kg × 10 (sample),دجاج مجمد 1 كجم × 10 (عينة),frozen,Case · 10 kg,128,2,,,frozen,270,2027-05-31,40','Labneh 1 kg × 6 (sample),لبنة 1 كجم × 6 (عينة),dairy,Case · 6 kg,84,1,,,chilled,30,,25'].join('\n');
const parseCSV=txt=>{ const out=[]; let row=[],cur='',q=false; for(let i=0;i<txt.length;i++){ const c=txt[i]; if(q){ if(c==='"'){ if(txt[i+1]==='"'){ cur+='"'; i++; } else q=false; } else cur+=c; } else if(c==='"') q=true; else if(c===','){ row.push(cur); cur=''; } else if(c==='\n'||c==='\r'){ if(c==='\r'&&txt[i+1]==='\n') i++; row.push(cur); out.push(row); row=[]; cur=''; } else cur+=c; } if(cur||row.length){ row.push(cur); out.push(row); } return out.filter(r=>r.some(x=>x.trim())); };
const gOf={rice:'sack',oil:'tin',dairy:'milk',frozen:'frozen',canned:'can',spice:'jar',pack:'box'};
const csvRows=txt=>{ const R=parseCSV(txt); if(!R.length) return {err:t('The file is empty','الملف فارغ')}; const H=R[0].map(h=>h.trim().toLowerCase()); const miss=CSV_COLS.filter(c=>!['tier1_from','tier1_pct'].includes(c)&&!H.includes(c)); if(miss.length) return {err:t('Missing columns: ','أعمدة ناقصة: ')+miss.join(', '),H};
 const today=new Date(now()).toISOString().slice(0,10);
 const rows=R.slice(1).map((r,i)=>{ const o={}; H.forEach((h,j)=>o[h]=(r[j]||'').trim()); const e=[]; if(!o.title_en) e.push(t('title missing','العنوان ناقص')); if(!CATS.some(c=>c[0]===o.category)) e.push(t('unknown category','فئة غير معروفة')); if(!(Number(o.price_excl_vat)>0)) e.push(t('price must be above 0','السعر يجب أن يكون أكبر من 0')); if(!STORE.some(s=>s[0]===o.storage)) e.push(t('storage must be ambient, chilled or frozen','التخزين: ambient أو chilled أو frozen')); if(!(o.best_before>today)) e.push(t('best_before missing or past','best_before ناقص أو منتهٍ'));
  return {n:i+2,o,e}; }); return {H,rows}; };
def('s.import',{t:()=>t('Import products','استيراد المنتجات'),back:'s.products',tab:'s.products',render:()=>{ const f=UI.csv; let h=`<div class="pad"><p class="why">${t('Add many products at once with a CSV file. New products are saved as drafts or sent for review.','أضف منتجات كثيرة دفعة واحدة بملف CSV. تُحفظ كمسودات أو تُرسل للمراجعة.')}</p><button type="button" class="lnk" data-act="csvtpl">${I('dl',16)} ${t('Download CSV template','حمّل قالب CSV')}</button></div>`;
 if(!f) h+=sec('',`<div class="pad drop"><p>${I('upload',28)}</p><label class="b b-sec" for="csvf">${I('file',18)}<span>${t('Choose CSV file','اختر ملف CSV')}</span></label><input id="csvf" class="vh" type="file" accept=".csv,text/csv" data-act="csvfile">${btn(t('Use sample file','استخدم الملف التجريبي'),{act:'csvsample',k:'ghost'})}</div>`);
 else { const P=csvRows(f.txt); h+=sec('',row({ic:'file',tone:'brand',t:esc(f.name),s:`${(f.txt.length/1024).toFixed(1)} KB`,end:btns(btn(t('Replace','استبدال'),{act:'csvrep',k:'ghost',sm:true}),btn(t('Remove','إزالة'),{act:'csvrm',k:'ghost',sm:true}))}));
  if(P.err) h+=`<div class="pad">${alert_('bad',t('Can’t read this file','تعذّرت قراءة الملف'),esc(P.err),{role:'alert'})}</div>`;
  else { const ok=P.rows.filter(r=>!r.e.length), bad=P.rows.filter(r=>r.e.length);
   h+=sec(t('Match columns','مطابقة الأعمدة'),`<table class="tbl"><thead><tr><th scope="col">${t('Column in file','العمود في الملف')}</th><th scope="col">${t('MENAFoods field','حقل منافودز')}</th></tr></thead><tbody>${P.H.map(c=>`<tr><td>${LTR(c)}</td><td>${CSV_COLS.includes(c)?I('check',16)+' '+LTR(c):`<span class="mut">${t('Not imported','لن يُستورد')}</span>`}</td></tr>`).join('')}</tbody></table>`);
   h+=sec(t('Preview','معاينة'),rows(P.rows.map(r=>({ic:r.e.length?'alert':'check',tone:r.e.length?'bad':'ok',t:esc(r.o.title_en||t('(no title)','(بدون عنوان)')),s:r.e.length?`${t('Row','الصف')} ${r.n}: ${r.e.join(' · ')}`:`${catName(r.o.category)} · ${M(Number(r.o.price_excl_vat))} · ${N(Number(r.o.quantity_cases)||0)} ${t('cases','كرتون')}`}))),{act:pill(bad.length?'warn':'ok',`${ok.length} ${t('ready','جاهز')}${bad.length?` · ${bad.length} ${t('skipped','مُتجاوز')}`:''}`)});
   h+=`<div class="pad">${chk('updq',t('Update quantities for products that already exist (matched by English title)','حدّث كميات المنتجات الموجودة (بمطابقة العنوان الإنجليزي)'),UI.updq!==false,{act:'updq'})}</div>`; } }
 return {b:h,dock:f&&!csvRows(f.txt).err?btn(t('Import products','استيراد المنتجات'),{act:'csvgo',full:true,dis:!csvRows(f.txt).rows.some(r=>!r.e.length)}):null}; }});
