 let h=sec('',`<div class="pad"><p class="lbl">${t('Payout balance','رصيد المدفوعات')} ${sample()}</p><p class="bigm">${M(p.net)}</p><p class="why">${t(`${p.O.length} delivered order(s) waiting for the next weekly payout (sample schedule)`,`${p.O.length} طلب مُسلّم بانتظار الدفعة الأسبوعية التالية (جدول تجريبي)`)}</p></div>`+row({ic:'bank',tone:'brand',t:t('Bank account','الحساب البنكي'),s:k.ok?LTR('SA•• •••• •••• •••• •••• '+k.iban.slice(-4)):t('Not added','غير مضاف'),go:'s.bank'}));
 h+=L.length?sec(t('Payouts','المدفوعات'),rows(L.map(x=>({ic:'wallet',tone:x.st==='paid'?'ok':'warn',t:`${t('Payout','دفعة')} ${LTR('#'+x.id)} · ${M(x.net)}`,s:`${dt(x.ts)} · ${t(`${x.orders.length} orders`,`${x.orders.length} طلبات`)}`,pill:x.st==='paid'?['ok',t('Paid','مدفوعة')]:['warn',t('Carried forward','مُرحّلة')],go:'s.payout?id='+x.id})))):`<div class="pad">${empty('wallet',t('Keep track of your payouts','تابع مدفوعاتك'),t('This is where you’ll see a list of all your payouts and the details of each transaction.','هنا ترى قائمة مدفوعاتك وتفاصيل كل عملية.'),btns(btn(t('View transactions','عرض العمليات'),{act:'gotrans',k:'sec'})))}</div>`;
