MK.REF['s.ratings']=['Fiverr · reviews — overall rating with sub-ratings, review list with Seller’s response; Turo · Business › Reviews — sort, review card with “Your response”','3bed62eb-973b-46bb-93ac-5e9a7bc4a301','screens',['164357cd-6b06-4aaa-bc65-17aba43c407c']];
const SUBR=MK.SUBR=[['q',['Product quality','جودة المنتج']],['d',['Delivered on time','التسليم في الموعد']],['c',['Communication','التواصل']]];
def('s.ratings',{t:()=>t('Ratings & reviews','التقييمات والمراجعات'),back:'s.more',tab:'s.more',render:()=>{ const R=S.reviews.filter(r=>r.sel==='s1'); if(!R.length) return empty('star',t('No reviews yet','لا تقييمات بعد'),t('Buyers can rate you after an order is delivered.','يمكن للمشترين تقييمك بعد تسليم الطلب.'));
 const avg=k=>R.reduce((a,r)=>a+(k?r.sub[k]:r.stars),0)/R.length;
 let h=sec('',`<div class="pad"><div class="stat-row"><b class="bigm">${avg().toFixed(1)}</b>${stars(avg())}</div><p class="why">${t(`${R.length} review(s)`,`${R.length} مراجعة`)}</p>${kv(SUBR.map(([k,l])=>[tt(l),`${avg(k).toFixed(1)} ★`]))}</div>`);
 h+=R.map(r=>{ const o=ordFor(r.ord); return `<article class="rev"><div class="oc-h"><span class="logo sm" aria-hidden="true">${esc(tt([o.buyer.en,o.buyer.ar]).slice(0,1))}</span><div class="rb"><b>${esc(tt([o.buyer.en,o.buyer.ar]))}</b><small>${ago(r.ts)} · ${t('Order','طلب')} ${LTR('#'+r.ord)}</small></div>${stars(r.stars)}</div>${r.tx?`<p>${esc(r.tx)}</p>`:''}${r.reply?`<div class="reply"><b>${t('Your response','ردك')}</b><p>${esc(r.reply)}</p></div>`:btn(t('Reply','رد'),{act:'revreply',arg:r.id,k:'sec',sm:true,lbl:t('Reply to review on order ','رد على مراجعة الطلب ')+r.ord})}</article>`; }).join('');
 return h; }});
ACT.revreply=id=>sheet(t('Reply publicly','رد علني'),`${fld('rv',t('Your response','ردك'),{ta:true,req:true,max:300,hint:t('Buyers see this under the review','يراه المشترون تحت المراجعة')})}${btns(btn(t('Post reply','انشر الرد'),{act:'revok',arg:id}),btn(t('Cancel','إلغاء'),{act:'shclose',k:'sec'}))}`);
ACT.revok=id=>{ const sh=document.querySelector('.sh-wrap'); const v=form(sh).rv; if(v.length<2){ const i=sh.querySelector('#f-rv'); i.setAttribute('aria-invalid','true'); i.focus(); toast(t('Write a reply','اكتب ردًا')); return; } S.reviews.find(r=>r.id===id).reply=v; save(); closeSheet(true); rr(); toast(t('Reply posted','نُشر الرد')); };

