def('s.support',{t:()=>t('Seller support','دعم البائعين'),back:()=>S.me.st==='approved'?'s.more':home(),tabOk:true,render:q=>{ const qq=(UI.hq||'').toLowerCase(); const L=HELP.filter(h=>!qq||(tt(h[1])+' '+tt(h[2])).toLowerCase().includes(qq)); const T=S.tickets.filter(x=>x.sel==='s1');
 let h=`<div class="pad"><h2 class="qh">${t('How can we help you today?','كيف نساعدك اليوم؟')}</h2></div><div class="search" role="search">${I('search',20)}<label class="vh" for="hq">${t('Search help','ابحث في المساعدة')}</label><input id="hq" type="search" data-act="hq" value="${esc(UI.hq||'')}" autocomplete="off" placeholder="${t('Search for help','ابحث عن مساعدة')}"></div>`;
 h+=sec(t('General topics','مواضيع عامة'),L.length?rows(L.map(x=>({ic:'help',tone:'brand',t:tt(x[1]),act:'helpt',arg:x[0]}))):`<p class="pad">${t('No topics match. Contact us below.','لا مواضيع مطابقة. تواصل معنا أدناه.')}</p>`);
 if(T.length) h+=sec(t('Your requests','طلباتك'),rows(T.map(x=>({ic:'doc',tone:x.st==='open'?'warn':'ok',t:esc(x.subj),s:`${LTR('#'+x.id)} · ${ago(x.ts)}`,s2:x.reply?esc(x.reply):'',pill:x.st==='open'?['warn',t('Open','مفتوح')]:['ok',t('Answered','تم الرد')]}))));
 h+=sec(t('Contact us','تواصل معنا'),rows([{ic:'chat',tone:'brand',t:t('Message seller support','راسل دعم البائعين'),s:t('Replies within 1 business day (sample)','الرد خلال يوم عمل (تجريبي)'),act:'tkt',arg:q.get('ord')||''}]));
 return h; }});
ACT.hq=v=>{ UI.hq=v; rr(); const i=document.getElementById('hq'); if(i){ i.focus(); i.setSelectionRange(i.value.length,i.value.length); } };
ACT.helpt=k=>{ const x=HELP.find(h=>h[0]===k); sheet(tt(x[1]),`<p class="why">${tt(x[2])}</p><p class="fine">${t('Sample help text — MENAFoods to write the real articles.','نص مساعدة تجريبي — تكتب منافودز المقالات الفعلية.')}</p>${btn(t('Done','تم'),{act:'shclose',full:true})}`); };
ACT.tkt=ord=>sheet(t('Message seller support','راسل دعم البائعين'),`${fld('tsub',t('Topic','الموضوع'),{req:true,opts:[['',t('Choose','اختر')]].concat(HELP.map(h=>[tt(h[1]),tt(h[1])]))})}${fld('tord',t('Order number','رقم الطلب'),{val:ord,ltr:true,max:10})}${fld('tmsg',t('How can we help?','كيف نساعدك؟'),{ta:true,req:true,max:600})}${btns(btn(t('Send','إرسال'),{act:'tktok'}),btn(t('Cancel','إلغاء'),{act:'shclose',k:'sec'}))}`);
ACT.tktok=()=>{ const sh=document.querySelector('.sh-wrap'); const f=form(sh); const bad=!f.tsub?'tsub':f.tmsg.length<5?'tmsg':null; if(bad){ const i=sh.querySelector('#f-'+bad); i.setAttribute('aria-invalid','true'); i.focus(); toast(bad==='tsub'?t('Choose a topic','اختر موضوعًا'):t('Describe the issue','صف المشكلة')); return; }
 const id=String(5000+(++S.seq.r)); S.tickets.unshift({id,sel:'s1',subj:f.tsub+(f.tord?' · #'+f.tord:''),msg:f.tmsg,ts:now(),st:'open'}); notify('admin','help',[`Seller support request #${id}`,`طلب دعم بائع ‎#${id}`],null); save(); closeSheet(true); rr(); toast(t(`Request #${id} sent`,`أُرسل الطلب ‎#${id}`)); };

