ACT.srejok=id=>{ const sh=document.querySelector('.sh-wrap'); const f=form(sh); if(!f.srr){ const e=sh.querySelector('#srr-e'); e.hidden=false; e.setAttribute('role','alert'); sh.querySelector('input[name=srr]').focus(); return; } const s=S.sellers.find(x=>x.id===id); s.st='rejected'; s.why=tt(SREJ.find(r=>r[0]===f.srr)[1])+(f.srn?' — '+f.srn:''); s.dec=now();
 if(s.me){ S.me.st='rejected'; S.me.why=s.why; notify('seller','alert',[`Changes needed: ${s.why}`,`مطلوب تعديلات: ${s.why}`],'s.setup'); } save(); closeSheet(true); rr(); toast(t('Sent to seller','أُرسل للبائع')); };

